ValidationRule.errorConditionFormula:
IF( ISNEW(),false,
IF ( RecordType.Id <> $Label.ABY_Meeting_notes_record_type, false,
IF( NULLVALUE( AB_Remuneration_actuelle__c, -1)>0,false,
IF( OR(TEXT(AB_Job_application_country__c) = "Belgique", TEXT(AB_Job_application_country__c) = "France"),false,true)
)
)
)
